const D=window.ZYNFL_DATA, M=window.ZYNFL_MEDIA||{logo:null,teamPhotos:{},rivalryPhotos:{},gallery:[]}, ADP26=window.ZYNFL_2026_ADP||{meta:{},players:[]};
const RIVALRY_ART={"the-bean-bowl":"assets/images/rivalries/the-bean-bowl.svg","lion-raven":"assets/images/rivalries/lion-raven.svg","seoul-food":"assets/images/rivalries/seoul-food.svg","fraternity-fued":"assets/images/rivalries/fraternity-fued.svg","durby":"assets/images/rivalries/durby.svg","house-divided":"assets/images/rivalries/house-divided.svg","intellectual-dominance":"assets/images/rivalries/intellectual-dominance.svg","i35":"assets/images/rivalries/i35.svg","custody-battle":"assets/images/rivalries/custody-battle.svg","metlife-crisis":"assets/images/rivalries/metlife-crisis.svg","eigenvalue":"assets/images/rivalries/eigenvalue.svg","summoner":"assets/images/rivalries/summoner.svg","oct13":"assets/images/rivalries/oct13.svg"};

const app=document.getElementById('app'), nav=[...document.querySelectorAll('.nav-link')], backdrop=document.getElementById('modalBackdrop'), modalContent=document.getElementById('modalContent');
let playerSearch='',playerPos='ALL',playerOwner='ALL',playerSort='points',draftYear=2026,draftPos='ALL',historyScope='all',matrixScope='all';
const num=x=>Number(x||0), fmt=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:2}), pct=x=>x==null?'—':`${(Number(x)*100).toFixed(1)}%`, money=x=>`$${Number(x||0).toLocaleString(undefined,{maximumFractionDigits:0})}`;
const initials=s=>String(s||'').split(/\s+/).map(x=>x[0]).join('').slice(0,3).toUpperCase();
const ordinal=n=>{const v=n%100;return `${n}${['th','st','nd','rd'][(v-20)%10]||['th','st','nd','rd'][v]||'th'}`};
function go(page){nav.forEach(n=>n.classList.toggle('active',n.dataset.page===page));document.querySelector('.main-nav').classList.remove('open');({home:renderHome,season2025:renderSeason2025,seasons:renderAllSeasons,history:renderHistory,players:renderPlayers,teams:renderTeams,rivalry:renderRivalry,gallery:renderGallery,draft:renderDraftCentral}[page]||renderHome)();window.scrollTo({top:0,behavior:'instant'});history.replaceState(null,'',`#${page}`)}
nav.forEach(n=>n.addEventListener('click',()=>go(n.dataset.page)));document.getElementById('mobileMenu').onclick=()=>document.querySelector('.main-nav').classList.toggle('open');document.getElementById('modalClose').onclick=closeModal;backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function openModal(x){modalContent.innerHTML=x;backdrop.hidden=false;document.body.style.overflow='hidden'}function closeModal(){backdrop.hidden=true;document.body.style.overflow=''}
function sectionHeading(k,t,d,extra=''){return `<div class="section-heading"><div><div class="kicker">${k}</div><h2>${t}</h2></div>${extra}</div>`}
function recordCard(s){return `<article class="record-card"><div class="record-title">${s.title}</div><div class="record-value">${s.value}</div><div class="record-detail">${s.owner}${s.team?` · ${s.team}`:''}${s.year?` · ${s.year}`:''}</div>${s.detail?`<div class="record-subdetail">${s.detail}</div>`:''}</article>`}
function currentTeam(owner){return D.owners[owner]?.currentTeam||owner}
function teamPhoto(owner){return M.teamPhotos?.[owner]||''}
function rivalryPhoto(id){return RIVALRY_ART[id]||M.rivalryPhotos?.[id]||''}

function rivalryClaim(R,latest){const x=R.beltHolder||latest?.winner||'';const loser=latest?(latest.winner===R.owners[0]?R.owners[1]:R.owners[0]):'';switch(R.id){case'the-bean-bowl':return `${x} is the true Mexican`;case'lion-raven':return `${x} holds the Belt`;case'seoul-food':return `${x} is the true Korean`;case'fraternity-fued':return `${x} is the better Pike Brother`;case'durby':return `${x} holds the family name`;case'house-divided':return `${x} keeps 1400`;case'intellectual-dominance':return `${x} intellectually dominates ${loser}`;case'i35':return `${x} is the true Texan`;case'custody-battle':return `${x} is Rick's true father`;case'metlife-crisis':return `${x} controls New York`;case'eigenvalue':return `${x} holds the Belt`;case'summoner':return `${x} is the better Summoner`;case'oct13':return `${x} is the Birthday Boy`;default:return `${x} holds the Belt`}}

function applyBrandMedia(){const el=document.querySelector('.brand-mark');if(el&&M.logo){el.classList.add('has-image');el.innerHTML=`<img src="${M.logo}" alt="ZYNFL logo">`}}
applyBrandMedia();
function championBanner(c){return `<div class="banner"><div class="banner-year">${c.year}</div><div class="banner-team">${c.team}</div><div class="banner-owner">${c.owner}</div><div class="banner-record">${c.record}</div></div>`}
function renderHome(){const m=D.meta, c=D.champions.find(x=>x.year===2025), all=D.awards.all.custom;app.innerHTML=`<div class="page"><section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">EST. 2024 · 12 FRANCHISES · REDRAFT · FAAB</div><h1><span class="accent">ZYN</span>FL</h1><p class="hero-deck">Two seasons of championships, bench disasters, waiver bidding, draft steals and grudges important enough to deserve their own trophy names.</p></div><div class="hero-side"><div class="hero-logo-lockup"><img src="data:image/png;base64," alt="ZYNFL logo"><div style="font-size:26px;font-weight:900;line-height:1.1">ZYNFL</div></div><div class="hero-side-label">Defending Champion</div><div class="hero-side-value">${c.team}</div><div class="hero-side-sub">${c.owner} · 2025 Champion · ${c.record} regular season</div></div></div></section>
<div class="stats-strip"><div class="wrap stat-grid"><div class="stat"><div class="stat-value">${m.completedSeasons}</div><div class="stat-label">Completed Seasons</div></div><div class="stat"><div class="stat-value">${m.games}</div><div class="stat-label">Games Archived</div></div><div class="stat"><div class="stat-value">${m.transactions}</div><div class="stat-label">Transactions</div></div><div class="stat"><div class="stat-value">${m.playerWeeks.toLocaleString()}</div><div class="stat-label">Player-Week Rows</div></div><div class="stat"><div class="stat-value">${D.rivalries.length}</div><div class="stat-label">Official Rivalries</div></div></div></div>
<section class="section dark"><div class="wrap">${sectionHeading('THE CHAMPIONSHIP HALL','Every banner so far.','Regular-season record shown beneath each champion.')}<div class="banners">${D.champions.map(championBanner).join('')}</div></div></section>
<section class="section"><div class="wrap">${sectionHeading('THE STATE OF ZYNFL','What two seasons have already told us.','A league with enough weekly data to measure not just who won, but who managed well.')}<div class="story-grid"><article class="story-card"><div class="eyebrow">2025 FINISH</div><h3>Leo finished the job.</h3><p>Jahmyr Gibbs Swift Johnson entered the playoffs as the #1 seed and beat Quinn 98.22–96.88 in the championship.</p></article><article class="story-card"><div class="eyebrow">THE WHAT-IF FILE</div><h3>Every bench decision is archived.</h3><p>Starter, bench and IR rows let ZYNFL track legal optimal lineups, missed points and losses that would have flipped with different start/sit decisions.</p></article></div></div></section>
<section class="section dark"><div class="wrap">${sectionHeading('LEAGUE PULSE','The archive underneath the jokes.','Draft position, FAAB, transactions and weekly roster decisions are all indexed.')}<div class="pulse-grid"><div class="pulse-card"><strong>${m.draftPicks}</strong><span>Draft Picks</span></div><div class="pulse-card"><strong>${m.fabAwards}</strong><span>FAAB Awards</span></div><div class="pulse-card"><strong>${m.completedTrades}</strong><span>Completed Trades</span></div><div class="pulse-card"><strong>${m.playoffGames}</strong><span>Playoff / Placement Games</span></div></div></div></section>
<section class="section alt"><div class="wrap">${sectionHeading('FROM THE RECORD BOOK','A few awards worth putting on the front page.','Career totals through 2025.')}<div class="record-grid">${[all.find(x=>x.title==='GOAT'),all.find(x=>x.title==='COTY'),all.find(x=>x.title==='Fantasy God'),all.find(x=>x.title==='Spectator Sport')].map(recordCard).join('')}</div></div></section></div>`}

function seasonRow(s){return `<tr><td><span class="rank-badge ${s.rank<=3?'top':''}">${s.rank}</span></td><td><strong>${s.owner}</strong><small style="display:block;color:#7b8997">${s.team}</small></td><td>${s.w}-${s.l}</td><td>${s.pf.toFixed(2)}</td><td>${s.pa.toFixed(2)}</td><td>${s.diff>=0?'+':''}${s.diff.toFixed(2)}</td><td>${pct(D.owners[s.owner].seasons.find(x=>x.year===Number(document.body.dataset.seasonYear||2025))?.lineupEff)}</td></tr>`}
function bracketMarkup(year){const s=D.seasons[String(year)], st=D.standings[String(year)];const seed=o=>st.find(x=>x.owner===o)?.rank||'';if(year===2025){return `<div class="bracket-wrap"><div class="bracket-byes"><span><b>#1 Leo</b> · First-round bye</span><span><b>#2 Rick</b> · First-round bye</span></div><div class="championship-bracket"><svg class="bracket-lines" viewBox="0 0 980 430" preserveAspectRatio="none"><path d="M270 90 H350"/><path d="M270 300 H350"/><path d="M630 90 H705 V205 H770"/><path d="M630 300 H705 V205"/></svg><div class="bracket-round-label qf-label">Quarterfinals</div><div class="bracket-round-label sf-label">Semifinals</div><div class="bracket-round-label final-label">Championship</div>${bmatch('qf-one','Quarterfinal',3,'Quinn',144.42,6,'Jack',103.56,'Quinn')}${bmatch('qf-two','Quarterfinal',4,'Liam',124.52,5,'Brock',79.70,'Liam')}${bmatch('sf-one','Semifinal',1,'Leo',106.02,4,'Liam',66.20,'Leo')}${bmatch('sf-two','Semifinal',2,'Rick',88.60,3,'Quinn',137.56,'Quinn')}${bmatch('final','Championship',1,'Leo',98.22,3,'Quinn',96.88,'Leo')}<div class="bracket-champ" style="position:absolute;left:730px;top:284px;width:250px;z-index:2">🏆 Leo · 2025 Champion</div></div><div class="placement-bracket"><article><small>3rd Place</small><strong>Liam 129.68</strong><span>over Rick 60.28</span></article><article><small>Final</small><strong>Leo 98.22</strong><span>over Quinn 96.88</span></article></div></div>`}
return `<div class="bracket-wrap"><div class="bracket-byes"><span><b>#1 Quinn</b> · First-round bye</span><span><b>#2 Chuck</b> · First-round bye</span></div><div class="championship-bracket"><svg class="bracket-lines" viewBox="0 0 980 430" preserveAspectRatio="none"><path d="M270 90 H350"/><path d="M270 300 H350"/><path d="M630 90 H705 V205 H770"/><path d="M630 300 H705 V205"/></svg><div class="bracket-round-label qf-label">Quarterfinals</div><div class="bracket-round-label sf-label">Semifinals</div><div class="bracket-round-label final-label">Championship</div>${bmatch('qf-one','Quarterfinal',3,'Tina',85.34,6,'Daniel',102.60,'Daniel')}${bmatch('qf-two','Quarterfinal',4,'Rick',164.38,5,'Jack',96.94,'Rick')}${bmatch('sf-one','Semifinal',1,'Quinn',137.12,6,'Daniel',168.04,'Daniel')}${bmatch('sf-two','Semifinal',2,'Chuck',132.38,4,'Rick',99.56,'Chuck')}${bmatch('final','Championship',2,'Chuck',127.02,6,'Daniel',99.38,'Chuck')}<div class="bracket-champ" style="position:absolute;left:730px;top:284px;width:250px;z-index:2">🏆 Chuck · 2024 Champion</div></div><div class="placement-bracket"><article><small>3rd Place</small><strong>Quinn 143.46</strong><span>over Rick 94.68</span></article><article><small>Final</small><strong>Chuck 127.02</strong><span>over Daniel 99.38</span></article></div></div>`}
function bmatch(cls,label,s1,o1,sc1,s2,o2,sc2,w){const row=(seed,o,sc)=>`<div class="bracket-team ${o===w?'advances':''}"><span class="bracket-seed">${seed}</span><div><strong>${o}</strong><small>${currentTeam(o)}</small></div><b>${Number(sc).toFixed(2)}</b></div>`;return `<article class="bracket-match ${cls}"><small>${label}</small>${row(s1,o1,sc1)}${row(s2,o2,sc2)}</article>`}
function awardGroups(scope){const a=D.awards[String(scope)];return `<div class="award-groups"><div><div class="award-group-title">Named League Awards</div><div class="record-grid">${a.custom.map(recordCard).join('')}</div></div><div><div class="award-group-title">Position Production</div><div class="record-grid">${a.position.map(recordCard).join('')}</div></div></div>`}
function renderSeason2025(){document.body.dataset.seasonYear=2025;const S=D.seasons['2025'], champ=D.owners[S.champion].seasons.find(x=>x.year===2025), topPF=D.standings['2025'].slice().sort((a,b)=>b.pf-a.pf)[0], coty=D.awards['2025'].custom.find(x=>x.title==='COTY');app.innerHTML=`<div class="page"><section class="season-hero"><div class="wrap season-hero-grid"><div><div class="eyebrow">2025 SEASON FILE</div><h1>LEO TAKES YEAR TWO</h1><p>Leo earned the #1 seed, survived Liam in the semifinal and edged Quinn by 1.34 points for the title.</p></div><div class="champion-lockup"><span>2025 Champion</span><strong>${S.championTeam}</strong><b>${S.champion} · ${S.record}</b><small>Championship: ${S.finalScore}</small></div></div></section><div class="stats-strip"><div class="wrap season-kpis"><div class="stat"><div class="stat-value">98.22</div><div class="stat-label">Leo · Final Score</div></div><div class="stat"><div class="stat-value">${topPF.pf.toFixed(2)}</div><div class="stat-label">Quinn · League-Best PF</div></div><div class="stat"><div class="stat-value">${coty.value}</div><div class="stat-label">${coty.owner} · COTY Efficiency</div></div><div class="stat"><div class="stat-value">${D.owners.Brock.seasons.find(x=>x.year===2025).transactions}</div><div class="stat-label">Brock · Transactions</div></div></div></div>
<section class="section"><div class="wrap">${sectionHeading('HOW 2025 FINISHED','Regular-season table.','Seeds use record, then points for.') }<div class="season-table-shell"><table class="season-table"><thead><tr><th>Seed</th><th>Manager</th><th>Record</th><th>PF</th><th>PA</th><th>Diff</th><th>Lineup Eff.</th></tr></thead><tbody>${D.standings['2025'].map(seasonRow).join('')}</tbody></table></div></div></section>
<section class="section dark"><div class="wrap">${sectionHeading('THE BRACKET','2025 playoffs.','Leo and Rick earned byes. Quinn came through the quarterfinal side of the bracket and pushed Leo to the final possession.')} ${bracketMarkup(2025)}</div></section>
<section class="section"><div class="wrap">${sectionHeading('2025 SUPERLATIVES','The awards only this season could produce.','Position totals use starter fantasy points; lineup awards use the legal optimal lineup model.')} ${awardGroups('2025')}</div></section>
<section class="section alt"><div class="wrap">${sectionHeading('TEAM FILES','Every 2025 franchise.','')}<div class="season-team-grid">${D.standings['2025'].map(s=>{const so=D.owners[s.owner].seasons.find(x=>x.year===2025),trs=D.trades.filter(t=>t.year===2025&&t.status==='Completed'&&(t.a===s.owner||t.b===s.owner));return `<article class="season-team-card"><div class="season-team-head"><div class="finish-badge">#${s.rank}</div><div><h3>${s.owner}</h3><small>${s.team}</small></div><div class="season-record">${s.w}-${s.l}<span>Regular</span></div></div><div class="season-team-stats"><div class="season-team-stat"><strong>${s.pf.toFixed(1)}</strong><span>PF</span></div><div class="season-team-stat"><strong>${s.pa.toFixed(1)}</strong><span>PA</span></div><div class="season-team-stat"><strong>${s.diff>=0?'+':''}${s.diff.toFixed(1)}</strong><span>Diff</span></div><div class="season-team-stat"><strong>${pct(so.lineupEff)}</strong><span>Lineup</span></div><div class="season-team-stat"><strong>${so.transactions}</strong><span>Moves</span></div></div><p class="season-team-story">${SEASON2025_STORIES[s.owner]||''}</p>${trs.length?`<div class="season-team-trade"><strong>League trades:</strong> ${trs.map(t=>`${t.a} ↔ ${t.b}: ${t.players.join(', ')}`).join(' · ')}</div>`:''}</article>`}).join('')}</div></div></section>
<section class="section"><div class="wrap">${sectionHeading('2025 IN THE NFL','Stories that moved ZYNFL rosters.','')}<div class="news-grid">${SEASON2025_ARTICLES.map(a=>`<a class="news-card" href="${a.url}" target="_blank" rel="noopener noreferrer"><div class="news-source">${a.source}</div><h3>${a.title}</h3><p>${a.desc}</p><div class="news-affected">Affected: ${a.affected} ↗</div></a>`).join('')}</div></div></section></div>`}

function renderAllSeasons(){app.innerHTML=`<div class="page"><section class="page-hero"><div class="wrap"><div class="eyebrow">THE YEARBOOK</div><h1>All Seasons</h1></div></section><section class="section"><div class="wrap">${sectionHeading('SEASON ARCHIVE','Choose a year.','Completed seasons open into a detailed season file. The 2026 draft is complete, but no games have been played yet.')}<div class="season-grid">${[2025,2024].map(y=>{const s=D.seasons[String(y)];return `<button class="season-card live" data-year="${y}"><div class="season-status">Complete</div><div class="season-year">${y}</div><h3>${s.champion} · ${s.championTeam}</h3><p>${s.record} regular season · beat ${s.runnerUp} in the final</p></button>`}).join('')}<button class="season-card live" id="season2026Draft"><div class="season-status">Draft Complete</div><div class="season-year">2026</div><h3>180 picks are in</h3><p>Open the completed 2026 board in Draft Central.</p></button></div></div></section></div>`;document.querySelectorAll('.season-card[data-year]').forEach(b=>b.onclick=()=>openSeason(Number(b.dataset.year)));document.getElementById('season2026Draft').onclick=()=>go('draft')}
function openSeason(year){document.body.dataset.seasonYear=year;const s=D.seasons[String(year)], top=D.standings[String(year)][0];openModal(`<div class="modal-hero"><div class="eyebrow">${year} SEASON FILE</div><h2>${s.champion} · Champion</h2><p>${s.championTeam} · ${s.record} · Final ${s.finalScore}</p></div><div class="modal-body"><div class="modal-stat-grid"><div class="modal-stat"><strong>${s.runnerUp}</strong><span>Runner-Up</span></div><div class="modal-stat"><strong>${s.bronze}</strong><span>Third Place</span></div><div class="modal-stat"><strong>${s.topPF}</strong><span>Most PF</span></div><div class="modal-stat"><strong>${s.wall}</strong><span>Wall of Shame</span></div></div><div class="detail-card"><h3>Regular-Season Standings</h3><div class="timeline-grid">${D.standings[String(year)].map(x=>`<div class="timeline-item"><b>#${x.rank} · ${x.owner}</b><small>${x.team} · ${x.w}-${x.l}</small><strong>${x.pf.toFixed(1)} PF</strong></div>`).join('')}</div></div><div class="detail-card" style="margin-top:18px"><h3>Championship Bracket</h3><div style="overflow:visible">${bracketMarkup(year)}</div></div></div>`)}

function renderHistory(){const newManagers=['Akhil','Mitchell'];const career=D.ownerOrder.filter(o=>D.owners[o]).sort((a,b)=>{const ap=D.owners[a].regular.pct,bp=D.owners[b].regular.pct;if(ap==null&&bp!=null)return 1;if(bp==null&&ap!=null)return -1;if((bp??0)!==(ap??0))return (bp??0)-(ap??0);return D.owners[b].regular.w-D.owners[a].regular.w});app.innerHTML=`<div class="page"><section class="page-hero"><div class="wrap"><div class="eyebrow">THE PERMANENT RECORD</div><h1>League History</h1><p>Champions, shame, career leaderboards, superlatives, head-to-head records, trades and transaction behavior.</p></div></section><section class="section dark"><div class="wrap">${sectionHeading('CHAMPIONSHIP HALL','The banners.','Two completed seasons and two different champions.')}<div class="banners">${D.champions.map(championBanner).join('')}</div></div></section><section class="section"><div class="wrap">${sectionHeading('2026 LEAGUE RESET','Draft complete. New managers arrive.','Akhil and Mitchell begin with clean records; Daniel and Rick move to Historical Managers with every prior result and award still credited to them.')}<div class="pulse-grid"><div class="pulse-card"><strong>180</strong><span>2026 Draft Picks</span></div><div class="pulse-card"><strong>15</strong><span>Rounds</span></div><div class="pulse-card"><strong>2</strong><span>New Managers</span></div><div class="pulse-card"><strong>0-0</strong><span>Akhil & Mitchell Career Records</span></div></div><div class="owner-dna-grid" style="margin-top:18px">${newManagers.map(o=>{const first=D.drafts.find(d=>d.year===2026&&d.owner===o);return `<article class="owner-dna-card"><h3>${o}</h3><small>${D.owners[o].currentTeam}</small><div class="dna-stats"><div><strong>${ordinal(first.pick)}</strong><span>Draft Slot</span></div><div><strong>#${first.overall}</strong><span>First Selection</span></div><div><strong>0</strong><span>Games Played</span></div></div><div class="super-note">First ZYNFL pick: ${first.player}. No historical stats or superlatives were inherited.</div></article>`}).join('')}</div></div></section><section class="section"><div class="wrap">${sectionHeading('THE PODIUM','Gold, silver and bronze.','Third place comes from the championship-bracket third-place game.')}<table class="podium-table"><thead><tr><th>Year</th><th>Champion</th><th>Runner-Up</th><th>Third</th></tr></thead><tbody>${D.podium.map(p=>`<tr><td><b>${p.year}</b></td><td><span class="medal-dot gold"></span><strong>${p.gold}</strong> · ${p.goldTeam}</td><td><span class="medal-dot silver"></span><strong>${p.silver}</strong> · ${p.silverTeam}</td><td><span class="medal-dot bronze"></span><strong>${p.bronze}</strong> · ${p.bronzeTeam}</td></tr>`).join('')}</tbody></table></div></section><section class="section alt"><div class="wrap">${sectionHeading('CAREER LEADERBOARD','Career totals through the two completed seasons.','Akhil and Mitchell are listed at 0-0. Daniel, Rick and Calvin remain in the permanent record as historical managers.')}<div class="leaderboard-card"><table class="career-table"><thead><tr><th>Owner</th><th>W-L</th><th>Win %</th><th>PF</th><th>PA</th><th>Lineup Eff.</th><th>Transactions</th><th>Titles</th></tr></thead><tbody>${career.map(o=>{const x=D.owners[o];return `<tr><td><strong>${o}</strong><small style="display:block;color:#7b8997">${x.currentTeam}${x.active?'':' · Historical'}</small></td><td>${x.regular.w}-${x.regular.l}</td><td>${pct(x.regular.pct)}</td><td>${x.pf.toFixed(1)}</td><td>${x.pa.toFixed(1)}</td><td>${pct(x.avgLineupEff)}</td><td>${x.transactions}</td><td>${x.titles}</td></tr>`}).join('')}</tbody></table></div></div></section><section class="section"><div class="wrap"><div class="scope-bar">${sectionHeading('SUPERLATIVES','The awards wall.','All-Time uses career totals unless the card explicitly says “Season.” Historical awards stay with the manager who earned them.')}<div class="award-scope">${[['all','All-Time'],['2025','2025'],['2024','2024']].map(([k,l])=>`<button data-award-scope="${k}" class="${historyScope===k?'active':''}">${l}</button>`).join('')}</div></div><div id="historyAwards">${awardGroups(historyScope)}</div></div></section><section class="section h2h-light-section"><div class="wrap">${sectionHeading('HEAD-TO-HEAD','Who actually beats whom?','Only managers with completed games appear until 2026 results begin.')}<div class="scope-toggle">${[['all','All-Time'],['2025','2025'],['2024','2024']].map(([k,l])=>`<button class="scope-btn ${matrixScope===k?'active':''}" data-matrix-scope="${k}">${l}</button>`).join('')}</div><div id="h2hMatrix" style="margin-top:14px"></div></div></section><section class="section"><div class="wrap">${sectionHeading('TRADE NETWORK','Who actually deals with whom?','Completed historical trade events only; new managers enter once they make a league trade.')}<div id="tradeMatrix"></div></div></section><section class="section alt"><div class="wrap">${sectionHeading('WALL OF SHAME','Last place is permanent.','Last place is the Toilet Bowl loser / consolation-bracket loser.')}<div class="shame-list">${D.wallOfShame.map(x=>`<div class="shame-card"><div class="shame-year">${x.year}</div><b>${x.owner}</b><span>${x.team}</span></div>`).join('')}</div></div></section></div>`;document.querySelectorAll('[data-award-scope]').forEach(b=>b.onclick=()=>{historyScope=b.dataset.awardScope;document.querySelectorAll('[data-award-scope]').forEach(x=>x.classList.toggle('active',x.dataset.awardScope===historyScope));document.getElementById('historyAwards').innerHTML=awardGroups(historyScope)});document.querySelectorAll('[data-matrix-scope]').forEach(b=>b.onclick=()=>{matrixScope=b.dataset.matrixScope;document.querySelectorAll('[data-matrix-scope]').forEach(x=>x.classList.toggle('active',x.dataset.matrixScope===matrixScope));renderH2HMatrix()});renderH2HMatrix();renderTradeMatrix()}
function scopedGames(scope){return D.matchups.filter(g=>scope==='all'||String(g.year)===String(scope))}
function renderH2HMatrix(){const root=document.getElementById('h2hMatrix');if(!root)return;const played=new Set(D.matchups.flatMap(g=>[g.aOwner,g.bOwner]));const os=D.ownerOrder.filter(o=>played.has(o)&&(matrixScope==='all'||(matrixScope==='2025'?o!=='Calvin':o!=='Leo')));const games=scopedGames(matrixScope);const cell=(a,b)=>{if(a===b)return {text:'—',cls:'diagonal'};const gs=games.filter(g=>new Set([g.aOwner,g.bOwner]).has(a)&&new Set([g.aOwner,g.bOwner]).has(b)&&g.aOwner!==g.bOwner);if(!gs.length)return {text:'',cls:''};const w=gs.filter(g=>g.winner===a).length,l=gs.filter(g=>g.winner===b).length,t=gs.length-w-l,p=(w+.5*t)/gs.length;return {text:`${w}-${l}${t?'-'+t:''}`,cls:p>.5?'positive':p<.5?'negative':'even'}};root.innerHTML=`<div class="matrix-shell"><table class="matrix"><thead><tr><th class="matrix-owner-heading"><span class="matrix-full">Owner</span><span class="matrix-short">Mgr</span></th>${os.map(o=>`<th><span class="matrix-full">${o}</span><span class="matrix-short">${o.slice(0,2)}</span></th>`).join('')}</tr></thead><tbody>${os.map(a=>`<tr><td>${a}</td>${os.map(b=>{const c=cell(a,b);return `<td class="${c.cls}">${c.text}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`}
function renderTradeMatrix(){const root=document.getElementById('tradeMatrix');if(!root)return;const historical=new Set([...D.matchups.flatMap(g=>[g.aOwner,g.bOwner]),...D.trades.flatMap(t=>[t.a,t.b])]);const os=D.ownerOrder.filter(o=>historical.has(o));const count=(a,b)=>D.trades.filter(t=>t.status==='Completed'&&new Set([t.a,t.b]).has(a)&&new Set([t.a,t.b]).has(b)&&t.a!==t.b).length;root.innerHTML=`<div class="matrix-shell"><table class="matrix"><thead><tr><th class="matrix-owner-heading"><span class="matrix-full">Owner</span><span class="matrix-short">Mgr</span></th>${os.map(o=>`<th><span class="matrix-full">${o}</span><span class="matrix-short">${o.slice(0,2)}</span></th>`).join('')}</tr></thead><tbody>${os.map(a=>`<tr><td>${a}</td>${os.map(b=>a===b?'<td class="diagonal">—</td>':`<td class="${count(a,b)>0?'even':''}">${count(a,b)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="super-note">Vetoed trade: ${D.trades.filter(t=>t.status==='Vetoed').map(t=>`${t.year} · ${t.a} ↔ ${t.b}`).join(' · ')||'None'}</div>`}

function renderTeams(){const active=D.activeOwners, alumni=D.ownerOrder.filter(o=>!active.includes(o)&&D.owners[o]);const card=o=>{const x=D.owners[o];return `<button class="team-card ${x.active?'':'alumni'}" data-owner="${o}" aria-label="${o} - ${x.currentTeam}"><div class="team-photo ${teamPhoto(o)?'has-photo':''}">${teamPhoto(o)?`<img src="${teamPhoto(o)}" alt="${o}">`:`<div class="team-initials">${initials(o)}</div>`}</div><div class="team-body"><div class="team-name">${o}</div><div class="team-franchise">${x.currentTeam}</div><div class="team-record"><strong>${x.regular.w}-${x.regular.l}</strong><span>Overall Record</span></div>${teamTrophyCase(x)}</div></button>`};app.innerHTML=`<div class="page"><section class="page-hero"><div class="wrap"><div class="eyebrow">FRANCHISE FILES</div><h1>Teams</h1></div></section><section class="section"><div class="wrap">${sectionHeading('CURRENT LEAGUE','The 12 active managers.','Akhil and Mitchell enter in 2026 at 0-0; no prior franchise statistics carry over to them.')}<div class="team-grid">${active.map(card).join('')}</div>${alumni.length?`<div class="alumni-label">Historical Managers</div><div class="team-grid">${alumni.map(card).join('')}</div>`:''}</div></section></div>`;document.querySelectorAll('.team-card[data-owner]').forEach(b=>b.onclick=()=>showOwner(b.dataset.owner))}
function trophyShelf(x){const parts=[];if(x.titles)parts.push(`🏆 x${x.titles}`);if(x.silver)parts.push(`🥈 x${x.silver}`);if(x.bronze)parts.push(`🥉 x${x.bronze}`);if(x.brown)parts.push(`💩 x${x.brown}`);return `<div class="trophy-shelf">${parts.length?parts.map(p=>`<span class="trophy-unit">${p}</span>`).join(''):'<span class="trophy-unit" style="color:#9aa3ad;font-size:10px;font-style:italic">empty</span>'}</div>`}function teamTrophyCase(x){const parts=[];if(x.titles)parts.push(`🏆 x${x.titles}`);if(x.silver)parts.push(`🥈 x${x.silver}`);if(x.bronze)parts.push(`🥉 x${x.bronze}`);if(x.brown)parts.push(`💩 x${x.brown}`);return `<div class="team-trophy-case">${parts.length?parts.map(p=>`<span class="trophy-unit">${p}</span>`).join(''):'<span class="trophy-empty">empty</span>'}</div>`}
const SEASON2025_STORIES={"Leo":"The title run was built on a deep, stable draft core. Jahmyr Gibbs and James Cook supplied elite weekly RB production, Baker Mayfield became a huge value at pick 92, and Davante Adams plus D'Andre Swift kept the floor high. Leo made 23 transactions but never needed a trade, then survived the bracket and beat Quinn by 1.34 in the final.","Rick":"Rick won nine games with one of the league's lowest-maintenance rosters. Patrick Mahomes and Josh Jacobs supplied the spine of the team, while a 91.1% lineup efficiency and only 12 transactions show how little weekly scrambling was required. The roster earned the #2 seed without a single trade, but Quinn's semifinal explosion ended the title shot.","Quinn":"This was the league's best offense: 1,622.36 regular-season points and a 91.8% lineup efficiency. Bijan Robinson, Jaxon Smith-Njigba, George Pickens and Kyren Williams all smashed as draft picks, and Pickens' move to Dallas became one of the NFL season's biggest fantasy boosts. Quinn also worked two league trades, reached the championship, and lost the title by only 1.34 points.","Liam":"Josh Allen, Trey McBride and Ja'Marr Chase gave Liam star power at three premium positions, with Breece Hall adding another strong weekly piece. The roster scored 1,540.86 points with no trades and only 19 moves, so the season was mostly about riding the original build. An 8-6 finish became a semifinal appearance before Leo shut the door.","Brock":"Brock's 8-6 finish came with constant roster management: 37 transactions, the most in the league. Justin Herbert was a massive late value and Kenneth Walker produced when healthy, but Drake London's late-season knee injury removed one of Brock's biggest receivers at the worst time. The team still reached the postseason, then was held to 79.70 by Liam in the quarterfinals.","Jack":"Jack squeezed an 8-6 record out of a roster that ranked only sixth in points for, largely because his 91.8% lineup efficiency was among the league's best. Dak Prescott carried the QB slot, Chase Brown beat his draft cost, and Cameron Dicker was unusually valuable for a kicker. Jack made 32 moves but no trades, then ran into Quinn's 144.42-point quarterfinal.","Daniel":"Jonathan Taylor was the engine of the entire season, giving Daniel 322.8 starter points after a second-round selection and finishing the NFL year with 1,585 rushing yards and 18 rushing touchdowns. Travis Etienne was the other major draft hit, but the rest of the roster never matched Taylor's ceiling. Daniel made only 12 transactions, finished 7-7, and missed the playoff field.","Santi":"The roster had talent, but lineup decisions were the season's defining problem: 84.1% efficiency was the lowest mark in the league. De'Von Achane was a monster, and Santi was aggressive in two major trades, including the Justin Jefferson/Ashton Jeanty/Ladd McConkey deal with Nick and a tight-end swap with Isaac. The activity created upside, but too many usable points stayed out of the starting lineup.","Nick":"Christian McCaffrey and Jalen Hurts gave Nick two of the league's biggest individual producers; McCaffrey went on to lead the NFL with a historic 413 regular-season touches. The problem was everything around them: 85.1% lineup efficiency, a 6-8 record and 1,404.5 points for. Nick made 32 moves and the blockbuster trade with Santi, but the supporting cast never turned the star production into a playoff seed.","Chuck":"Chuck actually managed the lineup well \u2014 91.0% efficiency \u2014 but the roster did not generate enough total offense. Amon-Ra St. Brown was the clear WR1 and Jaylen Waddle plus Jaylen Warren were useful, but St. Brown's late ankle injury added pressure to an already thin scoring profile. With only 13 transactions and no trades, there was not much midseason reinvention, and the defending champion fell to 5-9.","Isaac":"Isaac spent the season trying to rework a roster that finished last in points for. Saquon Barkley, Jordan Love and Chris Olave had productive stretches, but the overall build lacked enough weekly ceiling and the lineup efficiency settled at 86.0%. Two trades \u2014 with Quinn and Santi \u2014 reshaped the roster, yet 28 transactions could not prevent an 11th-place regular-season finish.","Tina":"Puka Nacua and Derrick Henry delivered real star production, but the rest of the roster could not keep pace and Tina also absorbed 1,550.26 points against. The team made 20 moves and one trade with Quinn involving Jauan Jennings, J.J. McCarthy and Kyler Murray, but the turnaround never came. A 4-10 record left Big Nix Energy in last place despite not having the league's fewest points for."};
const SEASON2025_ARTICLES=[{"source":"NFL.com","title":"George Pickens trade fallout: Cowboys land missing piece?","desc":"Dallas' trade for Pickens changed his fantasy environment before Quinn drafted him into one of the league's best offenses.","affected":"Quinn \u00b7 George Pickens","url":"https://www.nfl.com/news/george-pickens-trade-fallout-cowboys-steelers-nfl-2025"},{"source":"NFL.com","title":"Falcons QB Michael Penix Jr., WR Drake London suffer knee injuries","desc":"London's late knee injury became a major stretch-run problem for Brock's receiving corps.","affected":"Brock \u00b7 Drake London","url":"https://www.nfl.com/news/falcons-qb-michael-penix-jr-knee-injury-panthers"},{"source":"NFL.com","title":"Amon-Ra St. Brown exits loss with ankle injury","desc":"A late-season ankle injury hit Chuck's top wide receiver during the fantasy playoff push.","affected":"Chuck \u00b7 Amon-Ra St. Brown","url":"https://www.nfl.com/news/lions-wr-amon-ra-st-brown-ruled-out-thursday-vs-packers-with-ankle-injury"},{"source":"NFL.com","title":"Christian McCaffrey named 2025 Comeback Player of the Year","desc":"CMC returned to a full season and a record-setting workload, carrying Nick's roster even while the team struggled around him.","affected":"Nick \u00b7 Christian McCaffrey","url":"https://www.nfl.com/news/christian-mccaffrey-49ers-rb-comeback-player-of-year-2025"},{"source":"Seahawks.com","title":"Jaxon Smith-Njigba's remarkable season continues","desc":"JSN's breakout became one of Quinn's biggest draft wins and helped power the league's highest-scoring team.","affected":"Quinn \u00b7 Jaxon Smith-Njigba","url":"https://www.seahawks.com/news/jaxon-smith-njigba-s-remarkable-season-continues-with-big-performance-in-win-over-commanders"},{"source":"NFL.com","title":"2025 running back rankings: McCaffrey, Taylor and the league's best","desc":"The season recap highlights Jonathan Taylor's 1,585 rushing yards and 18 rushing TDs, the centerpiece of Daniel's roster.","affected":"Daniel \u00b7 Jonathan Taylor","url":"https://www.nfl.com/news/nfl-starting-running-back-rankings-1-64-2025-nfl-season"},{"source":"NFL.com","title":"2025 receiving leaders","desc":"The final receiving table shows how massive Puka Nacua, JSN, Pickens and Amon-Ra were for several ZYNFL teams.","affected":"Tina \u00b7 Quinn \u00b7 Chuck","url":"https://www.nfl.com/stats/player-stats/category/receiving/2025/reg/all/receivingyards/desc"},{"source":"NFL.com","title":"Jahmyr Gibbs 2025 career stats","desc":"Gibbs finished with 1,223 rushing yards, 13 rushing TDs and 616 receiving yards as Leo's championship centerpiece.","affected":"Leo \u00b7 Jahmyr Gibbs","url":"https://www.nfl.com/players/jahmyr-gibbs/stats/career"}];
function playerTrophyCase(p){const counts={gold:0,silver:0,bronze:0,brown:0},seen=new Set();for(const h of (p.history||[])){const key=`${h.year}|${h.owner}|${h.team}`;if(seen.has(key))continue;seen.add(key);const pod=D.podium.find(x=>x.year===h.year),sh=D.wallOfShame.find(x=>x.year===h.year);if(pod){if(pod.gold===h.owner||pod.goldTeam===h.team)counts.gold++;if(pod.silver===h.owner||pod.silverTeam===h.team)counts.silver++;if(pod.bronze===h.owner||pod.bronzeTeam===h.team)counts.bronze++;}if(sh&&(sh.owner===h.owner||sh.team===h.team))counts.brown++;}const parts=[];if(counts.gold)parts.push(`🏆 x${counts.gold}`);if(counts.silver)parts.push(`🥈 x${counts.silver}`);if(counts.bronze)parts.push(`🥉 x${counts.bronze}`);if(counts.brown)parts.push(`💩 x${counts.brown}`);return `<div class="player-trophy-case">${parts.length?parts.map(x=>`<span class="ptrophy">${x}</span>`).join(''):'<span class="empty">empty</span>'}</div>`}

function showOwner(o){const x=D.owners[o],r=D.rivalries.filter(q=>q.owners.includes(o)),draft26=D.drafts.filter(d=>d.year===2026&&d.owner===o).sort((a,b)=>a.overall-b.overall);const seasonTimeline=x.seasons.length?x.seasons.map(s=>`<div class="timeline-item"><b>${s.year} · #${s.rank}</b><small>${s.team} · ${s.record}</small><strong>${s.pf.toFixed(1)} PF</strong></div>`).join(''):'<span class="tag">No completed ZYNFL games yet</span>';const bestDrafts=x.topDrafts.length?x.topDrafts.slice(0,5).map(d=>`<div class="timeline-item"><b>${d.year} · Pick ${d.overall}</b><small>${d.player} · ${d.position}</small><strong>${d.starterPoints.toFixed(1)} pts</strong></div>`).join(''):'<span class="tag">No completed-season production yet</span>';openModal(`<div class="modal-hero"><div class="modal-hero-grid"><div class="modal-avatar">${teamPhoto(o)?`<img src="${teamPhoto(o)}" alt="${o}" style="width:100%;height:100%;object-fit:cover;border-radius:50%;display:block">`:initials(o)}</div><div><div class="eyebrow">MANAGER FILE</div><h2>${o}</h2><p>${x.currentTeam}${x.active?'':' · Historical member'}</p>${trophyShelf(x)}</div></div></div><div class="modal-body"><div class="modal-stat-grid"><div class="modal-stat"><strong>${x.regular.w}-${x.regular.l}</strong><span>Regular Record</span></div><div class="modal-stat"><strong>${pct(x.avgLineupEff)}</strong><span>Avg Lineup Eff.</span></div><div class="modal-stat"><strong>${x.transactions}</strong><span>Transactions</span></div><div class="modal-stat"><strong>${money(x.faabSpent)}</strong><span>FAAB Spent</span></div></div><div class="detail-grid"><div class="detail-card"><h3>Team Names Used</h3><div class="tag-list">${x.aliases.map(a=>`<span class="tag">${a}</span>`).join('')}</div></div><div class="detail-card"><h3>Official Rivalries</h3><div class="tag-list">${r.length?r.map(q=>`<span class="tag">${q.name}</span>`).join(''):'<span class="tag">None listed</span>'}</div></div><div class="detail-card"><h3>Season Timeline</h3><div class="timeline-grid">${seasonTimeline}</div></div><div class="detail-card"><h3>Best Draft Contributors</h3><div class="timeline-grid">${bestDrafts}</div></div>${draft26.length?`<div class="detail-card" style="grid-column:1/-1"><h3>2026 Draft Class</h3><div class="timeline-grid">${draft26.map(d=>`<div class="timeline-item"><b>#${d.overall} · ${d.player}</b><small>Round ${d.round}, Pick ${d.pick} · ${d.position}</small><strong>${d.team}</strong></div>`).join('')}</div></div>`:''}</div></div>`)}

function renderPlayers(){const owners=['ALL',...D.ownerOrder],pos=['ALL','QB','RB','WR','TE','K','DEF'];app.innerHTML=`<div class="page"><section class="page-hero"><div class="wrap"><div class="eyebrow">THE PLAYER INDEX</div><h1>Players</h1></div></section><section class="section"><div class="wrap"><div class="search-panel"><div class="directory-controls"><input id="playerSearch" class="search-input" placeholder="Search player…" value="${playerSearch}"><select id="playerPos" class="filter-select">${pos.map(p=>`<option ${p===playerPos?'selected':''}>${p}</option>`).join('')}</select><select id="playerOwner" class="filter-select">${owners.map(o=>`<option ${o===playerOwner?'selected':''}>${o}</option>`).join('')}</select><select id="playerSort" class="filter-select"><option value="points" ${playerSort==='points'?'selected':''}>Starter Points</option><option value="draft" ${playerSort==='draft'?'selected':''}>Best Avg Draft Position</option><option value="starts" ${playerSort==='starts'?'selected':''}>Starts</option><option value="name" ${playerSort==='name'?'selected':''}>Name</option></select></div><div id="playerResults"></div></div></div></section></div>`;document.getElementById('playerSearch').oninput=e=>{playerSearch=e.target.value;drawPlayers()};document.getElementById('playerPos').onchange=e=>{playerPos=e.target.value;drawPlayers()};document.getElementById('playerOwner').onchange=e=>{playerOwner=e.target.value;drawPlayers()};document.getElementById('playerSort').onchange=e=>{playerSort=e.target.value;drawPlayers()};drawPlayers()}
function drawPlayers(){const root=document.getElementById('playerResults');if(!root)return;let rows=D.players.filter(p=>(!playerSearch||p.name.toLowerCase().includes(playerSearch.toLowerCase()))&&(playerPos==='ALL'||p.position===playerPos)&&(playerOwner==='ALL'||p.owners.includes(playerOwner)));rows=rows.slice().sort((a,b)=>playerSort==='draft'?((a.avgDraft??999)-(b.avgDraft??999)):playerSort==='starts'?(b.starts-a.starts):playerSort==='name'?a.name.localeCompare(b.name):(b.starterPoints-a.starterPoints));const shown=rows.slice(0,90);root.innerHTML=`<div class="search-meta">${rows.length} matching players · showing ${shown.length}</div><div class="player-results">${shown.map(p=>{const d26=p.drafts.find(d=>d.year===2026);return `<button class="player-result" data-player="${encodeURIComponent(p.key)}"><div><strong>${p.name}</strong><small>${d26?`2026 · ${d26.owner} · ${d26.team}`:(p.owners.join(', ')||'Rostered')}</small><span class="draft-meta">${d26?`Drafted #${d26.overall} · R${d26.round} P${d26.pick}`:(p.avgDraft?`Avg draft ${p.avgDraft}`:'Undrafted')} · ${p.starts} career starts</span></div><div class="player-result-right"><div class="pos-team-stack"><span class="pos-badge">${p.position}</span></div><div class="draft-value">${p.starterPoints.toFixed(1)}<small style="display:block">career starter pts</small></div></div></button>`}).join('')}</div>`;document.querySelectorAll('.player-result[data-player]').forEach(b=>b.onclick=()=>showPlayer(decodeURIComponent(b.dataset.player)))}
function showPlayer(k){const p=D.players.find(x=>x.key===k);if(!p)return;const current=p.drafts.find(d=>d.year===2026);openModal(`<div class="modal-hero"><div class="modal-hero-grid"><div class="modal-avatar">${p.position}</div><div><div class="eyebrow">PLAYER FILE</div><h2>${p.name}</h2><p>${current?`2026: ${current.owner} · ${current.team} · Pick #${current.overall}`:`${p.owners.join(' · ')||'No roster owner'} · ${p.seasons.join(', ')||'No weekly appearances'}`}</p></div></div></div><div class="modal-body"><div class="modal-stat-grid"><div class="modal-stat"><strong>${p.starts}</strong><span>Career Starts</span></div><div class="modal-stat"><strong>${p.starterPoints.toFixed(1)}</strong><span>Career Starter Points</span></div><div class="modal-stat"><strong>${p.avgDraft??'—'}</strong><span>Avg Overall Draft</span></div><div class="modal-stat"><strong>${p.drafts.length}</strong><span>Times Drafted</span></div></div><div class="detail-grid"><div class="detail-card"><h3>Trophy Case</h3>${playerTrophyCase(p)}</div><div class="detail-card"><h3>Draft History</h3><div class="timeline-grid">${p.drafts.length?p.drafts.slice().sort((a,b)=>b.year-a.year).map(d=>`<div class="timeline-item"><b>${d.year} · #${d.overall}</b><small>Round ${d.round}, Pick ${d.pick} · ${d.owner}</small><strong>${d.team}${d.year<2026?` · ${d.starterPoints.toFixed(1)} pts`:''}</strong></div>`).join(''):'<span class="tag">Undrafted in the archived drafts</span>'}</div></div><div class="detail-card" style="grid-column:1/-1"><h3>Roster History</h3><div class="timeline-grid">${p.history.slice().sort((a,b)=>b.year-a.year).map(h=>`<div class="timeline-item"><b>${h.year} · ${h.owner}</b><small>${h.team}${h.year===2026?' · Drafted roster, season not started':` · ${h.starts} starts · ${h.bench} bench`}</small><strong>${h.year===2026?'2026 roster':`${h.starterPoints.toFixed(1)} pts`}</strong></div>`).join('')}</div></div></div></div>`)}


function galleryItems(){return (M.gallery||[]).map((x,i)=>({...x,id:x.id||`built-${i}`}))}
function drawGallery(){const root=document.getElementById('galleryGrid');if(!root)return;const items=galleryItems();root.innerHTML=items.length?`<div class="gallery-grid">${items.map(x=>`<article class="gallery-card"><img src="${x.src}" alt="${x.caption||'ZYNFL league photo'}" loading="lazy"><div class="gallery-card-body"><div class="gallery-caption">${x.caption||''}</div></div></article>`).join('')}</div>`:`<div class="gallery-empty"><strong>No photos available.</strong></div>`}
function renderGallery(){app.innerHTML=`<div class="page"><section class="page-hero"><div class="wrap"><div class="eyebrow">LEAGUE LIFE</div><h1>Photo Gallery</h1><p>Trips, drafts, watch parties, victories, humiliations, and everything else worth preserving.</p></div></section><section class="section"><div class="wrap">${sectionHeading('THE CAMERA ROLL','The league off the spreadsheet.','')}<div id="galleryGrid"></div></div></section></div>`;drawGallery()}

function rivalrySorted(R){return R.games.slice().sort((a,b)=>b.year-a.year||Number((b.stage.match(/(\d+)$/)||[])[1]||0)-Number((a.stage.match(/(\d+)$/)||[])[1]||0))}
function renderRivalry(){app.innerHTML=`<div class="page"><section class="page-hero"><div class="wrap"><div class="eyebrow">THE BAD BLOOD DIRECTORY</div><h1>Rivalries</h1><p>Thirteen official ZYNFL rivalries.</p></div></section><section class="section"><div class="wrap">${sectionHeading('RIVALRY WALL','Choose a rivalry.','')}<div class="rivalry-library">${D.rivalries.map(R=>{const games=rivalrySorted(R),latest=games[0];return `<button class="rivalry-icon-card" data-rivalry="${R.id}"><div class="rivalry-icon-logo">${rivalryPhoto(R.id)?`<img src="${rivalryPhoto(R.id)}" alt="${R.name}">`:`<span>${R.owners.map(initials).join('×')}</span>`}</div><strong>${R.name}</strong><small>${R.owners.join(' vs ')}</small><em>${rivalryClaim(R,latest)}</em></button>`}).join('')}</div></div></section><div id="rivalryDetail"></div></div>`;document.querySelectorAll('[data-rivalry]').forEach(b=>b.onclick=()=>showRivalry(b.dataset.rivalry));if(D.rivalries[0])showRivalry(D.rivalries[0].id)}
function showRivalry(id){const R=D.rivalries.find(x=>x.id===id);if(!R)return;document.querySelectorAll('[data-rivalry]').forEach(b=>b.classList.toggle('active',b.dataset.rivalry===id));const [a,b]=R.owners,games=rivalrySorted(R),latest=games[0],aw=games.filter(g=>g.winner===a).length,bw=games.filter(g=>g.winner===b).length,ap=games.reduce((s,g)=>s+g.aScore,0),bp=games.reduce((s,g)=>s+g.bScore,0),claim=rivalryClaim(R,latest);document.getElementById('rivalryDetail').innerHTML=`<section class="section rivalry-detail-section"><div class="wrap"><div class="rivalry-grid"><div class="rivalry-poster"><div class="rivalry-poster-title"><span>ZYNFL PRESENTS</span><h2>${R.name.toUpperCase()}</h2></div><div class="rivalry-emblem"><img src="${rivalryPhoto(R.id)}" alt="${R.name}"></div><div class="rivalry-faces"><div class="rivalry-face"><div class="rivalry-avatar">${teamPhoto(a)?`<img src="${teamPhoto(a)}" alt="${a}">`:initials(a)}</div><strong>${a}</strong></div><div class="rivalry-vs">VS</div><div class="rivalry-face"><div class="rivalry-avatar">${teamPhoto(b)?`<img src="${teamPhoto(b)}" alt="${b}">`:initials(b)}</div><strong>${b}</strong></div></div></div><div class="belt-card"><div class="eyebrow">CURRENT BRAGGING RIGHTS</div><div class="claim-icon"><img src="${rivalryPhoto(R.id)}" alt=""></div><h2 class="rivalry-claim">${claim}</h2><p>${latest?`Most recent meeting: ${latest.stage} of ${latest.year}, ${Math.max(latest.aScore,latest.bScore).toFixed(2)}–${Math.min(latest.aScore,latest.bScore).toFixed(2)}.`:'No meeting yet.'}</p><div class="series-stats"><div class="series-stat"><strong>${aw}–${bw}</strong><span>${aw===bw?'Series tied':`${aw>bw?a:b} leads`}</span></div><div class="series-stat"><strong>${ap.toFixed(2)}</strong><span>${a} Points</span></div><div class="series-stat"><strong>${bp.toFixed(2)}</strong><span>${b} Points</span></div></div></div></div></div></section><section class="section alt"><div class="wrap">${sectionHeading('EVERY MEETING',`The complete ${R.name}.`,'')}<div class="rivalry-games">${games.map((g,i)=>`<article class="rivalry-game"><div class="rg-date"><strong>${g.year}</strong><br>${g.stage}</div><div class="rivalry-score ${g.winner===a?'winner':'loser'}">${a} · ${g.aTeam}<br><strong>${g.aScore.toFixed(2)}</strong></div><div class="rivalry-score ${g.winner===b?'winner':'loser'}">${b} · ${g.bTeam}<br><strong>${g.bScore.toFixed(2)}</strong></div><div class="rg-belt"><strong>${g.winner}</strong>${i===0?'<span class="belt-tag">Latest</span>':''}</div></article>`).join('')}</div></div></section>`}
function renderDraftCentral(){const years=[2026,2025,2024];app.innerHTML=`<div class="page"><section class="page-hero"><div class="wrap"><div class="eyebrow">SNAKE DRAFT HQ</div><h1>Draft Central</h1><p>The 2026 ZYNFL draft is complete. Browse every pick by overall number, round, player, manager and team, with the 2024–2025 boards preserved underneath.</p></div></section><div class="stats-strip"><div class="wrap stat-grid"><div class="stat"><div class="stat-value">180</div><div class="stat-label">2026 Picks</div></div><div class="stat"><div class="stat-value">15</div><div class="stat-label">Rounds</div></div><div class="stat"><div class="stat-value">12</div><div class="stat-label">Managers</div></div><div class="stat"><div class="stat-value">${D.meta.draftPicks}</div><div class="stat-label">All-Time Draft Picks</div></div><div class="stat"><div class="stat-value">2</div><div class="stat-label">New Managers</div></div></div></div><section class="section"><div class="wrap">${sectionHeading('DRAFT BOARD','Three completed ZYNFL drafts.','Use the year and position filters. 2026 shows the completed current roster draft; 2024–2025 also include eventual starter production.')}<div class="draft-year-toggle">${years.map(y=>`<button class="${draftYear===y?'active':''}" data-draft-year="${y}">${y}</button>`).join('')}</div><div class="draft-toolbar">${['ALL','QB','RB','WR','TE','K','DEF'].map(p=>`<button class="draft-pos-btn ${draftPos===p?'active':''}" data-pos="${p}">${p}</button>`).join('')}</div><div id="draftBoard"></div></div></section><section class="section alt"><div class="wrap">${sectionHeading('BOARD CONTEXT','How each manager built the roster.','2026 cards show draft slot, first three picks and positional construction. Historical cards retain production context.')}<div id="draftDNA"></div></div></section></div>`;document.querySelectorAll('[data-draft-year]').forEach(b=>b.onclick=()=>{draftYear=Number(b.dataset.draftYear);document.querySelectorAll('[data-draft-year]').forEach(x=>x.classList.toggle('active',Number(x.dataset.draftYear)===draftYear));drawDraft()});document.querySelectorAll('.draft-pos-btn').forEach(b=>b.onclick=()=>{draftPos=b.dataset.pos;document.querySelectorAll('.draft-pos-btn').forEach(x=>x.classList.toggle('active',x.dataset.pos===draftPos));drawDraft()});drawDraft()}
function drawDraft(){const root=document.getElementById('draftBoard');if(!root)return;const rows=D.drafts.filter(x=>x.year===draftYear&&(draftPos==='ALL'||x.position===draftPos)).sort((a,b)=>a.overall-b.overall);if(draftYear===2026){root.innerHTML=`<div class="draft-table-shell"><table class="draft-table"><thead><tr><th>Overall</th><th>Round</th><th>Player</th><th>Pos</th><th>NFL</th><th>Manager</th><th>ZYNFL Team</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="draft-rank">${x.overall}</td><td><span class="round-pill">R${x.round} · P${x.pick}</span></td><td><strong>${x.player}</strong></td><td><span class="pos-badge">${x.position}</span></td><td>${x.nflTeam||'—'}</td><td><strong>${x.owner}</strong></td><td>${x.team}</td></tr>`).join('')}</tbody></table></div><div class="draft-source-note">Completed 2026 ZYNFL draft · 180 actual Yahoo selections · season production has not started yet.</div>`;const dna=D.draftDNA['2026']||[];document.getElementById('draftDNA').innerHTML=`<div class="owner-dna-grid">${dna.map(x=>`<article class="owner-dna-card"><h3>${x.owner}</h3><small>${x.team}</small><div class="dna-stats"><div><strong>${ordinal(x.slot)}</strong><span>Draft Slot</span></div><div><strong>#${x.firstOverall}</strong><span>First Pick</span></div><div><strong>${Object.values(x.positionCounts).reduce((a,b)=>a+b,0)}</strong><span>Total Picks</span></div></div><div class="position-chips">${Object.entries(x.positionCounts).sort().map(([p,n])=>`<span>${p} ×${n}</span>`).join('')}</div><div class="super-note">First three: ${x.firstThree.join(' · ')}</div></article>`).join('')}</div>`;return}root.innerHTML=`<div class="draft-table-shell"><table class="draft-table"><thead><tr><th>Overall</th><th>Round</th><th>Player</th><th>Pos</th><th>Manager</th><th>Team</th><th>Starts</th><th>Starter Points</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="draft-rank">${x.overall}</td><td><span class="round-pill">R${x.round} · P${x.pick}</span></td><td><strong>${x.player}</strong></td><td><span class="pos-badge">${x.position}</span></td><td><strong>${x.owner}</strong></td><td>${x.team}</td><td>${x.starts}</td><td class="draft-contrib">${x.starterPoints.toFixed(1)}</td></tr>`).join('')}</tbody></table></div><div class="draft-source-note">Completed ${draftYear} ZYNFL draft. Actual picks, not market ADP.</div>`;const dna=D.draftDNA[String(draftYear)]||[];document.getElementById('draftDNA').innerHTML=`<div class="owner-dna-grid">${dna.map(x=>`<article class="owner-dna-card"><h3>${x.owner}</h3><small>${x.team}</small><div class="dna-stats"><div><strong>${ordinal(x.slot)}</strong><span>Draft Slot</span></div><div><strong>${x.totalStarterPoints.toFixed(0)}</strong><span>Drafted Starter Pts</span></div><div><strong>#${x.bestPickOverall}</strong><span>Best Contributor Pick</span></div></div><div class="position-chips">${Object.entries(x.positionCounts).sort().map(([p,n])=>`<span>${p} ×${n}</span>`).join('')}</div><div class="super-note">First pick: ${x.firstPick} (#${x.firstOverall}) · Top contributor: ${x.bestPick}</div></article>`).join('')}</div>`}

document.getElementById('footerMeta').textContent=`Historical data through ${D.meta.dataThrough} · ${D.meta.playerWeeks.toLocaleString()} player-week rows · V${D.meta.version}`;
const start=(location.hash||'#home').slice(1);go(['home','season2025','seasons','history','players','teams','rivalry','gallery','draft'].includes(start)?start:'home');
